def get_telc_b1_ai_seed():
    return json.loads('{"exam_id": "exam_telc_b1_001", "title": "TELC Deutsch B1 - Übungstest 1 (KI-generiert)", "lesen": {"aufgaben": [{"aufgabe_num": 1, "typ": "zuordnung", "short_texts": [{"id": "A", "text": "Liebe Nachbarn, wir wollen unseren Stadtteil noch schöner und grüner machen. Jeden Samstag treffen wir uns ab 10 Uhr morgens auf der alten Wiese hinter der Post. Wir pflanzen gemeinsam bunte Blumen und frisches Gemüse. Jeder kann gerne mitmachen, auch Familien mit Kindern sind herzlich willkommen. Das ganze Werkzeug haben wir schon vor Ort, Sie müssen also nur gute Laune und etwas Zeit mitbringen. Nach der getanen Arbeit trinken wir alle zusammen gemütlich Kaffee und unterhalten uns. Kommen Sie einfach vorbei!"}, {"id": "B", "text": "Hallo zusammen! Mein Name ist Maria, ich bin 25 Jahre alt und wohne seit einem halben Jahr in Hamburg. Ich lerne fleißig Deutsch, möchte aber noch besser sprechen. Meine Muttersprache ist Spanisch. Deshalb suche ich eine nette Partnerin oder einen netten Partner für ein regelmäßiges Sprachtandem. Wir können uns einmal in der Woche in einem Café treffen und eine Stunde Spanisch sowie eine Stunde Deutsch sprechen. Ich interessiere mich sehr für Musik, Sport und Reisen. Schreib mir doch einfach eine kurze Nachricht!"}, {"id": "C", "text": "Am kommenden Sonntag findet auf dem großen Marktplatz in der Innenstadt wieder unser beliebter Flohmarkt statt. Von 8 bis 16 Uhr können Sie hier gut erhaltene Bücher, Kleidung, altes Spielzeug und schöne kleine Möbelstücke günstig kaufen. Es gibt auch viele Stände mit leckerem Essen und warmen Getränken für die ganze Familie. Wenn Sie selbst alte Dinge verkaufen möchten, melden Sie sich bitte bis spätestens Freitag auf unserer Webseite an. Die Gebühr für einen Stand beträgt nur 10 Euro."}, {"id": "D", "text": "Unser Sportverein bietet ab der nächsten Woche einen ganz neuen Sportkurs an. Der Kurs heißt \'Fit in den Tag\' und findet immer am Dienstagmorgen von 8 bis 9 Uhr in der großen Turnhalle am Park statt. Er ist für Anfänger und Fortgeschrittene jeden Alters bestens geeignet. Wir machen leichte Fitnessübungen für den ganzen Körper und trainieren unsere Kraft. Eine Anmeldung im Voraus ist nicht nötig, und die erste Probestunde ist für alle Interessierten natürlich kostenlos."}, {"id": "E", "text": "Haben Sie einen Hund oder eine Katze und fahren bald für ein paar Tage in den Urlaub? Wir sind eine freundliche Familie mit zwei lieben Kindern und wir mögen Tiere sehr. Da wir selbst in unserer Wohnung leider kein eigenes Haustier halten dürfen, bieten wir an, am Wochenende oder in den Ferien kostenlos auf Ihr Tier aufzupassen. Wir wohnen direkt am großen Stadtwald und können viel spazieren gehen. Melden Sie sich gerne bei uns!"}], "ueberschriften": [{"id": "a", "text": "Neuer Sportkurs am Abend"}, {"id": "b", "text": "Kostenlose Hilfe für Haustierbesitzer"}, {"id": "c", "text": "Billige Möbel im Internet kaufen"}, {"id": "d", "text": "Gemeinsam gärtnern im Stadtviertel"}, {"id": "e", "text": "Partner für Spanisch und Deutsch gesucht"}, {"id": "f", "text": "Neue Pflanzen für die eigene Wohnung kaufen"}, {"id": "g", "text": "Sprachen lernen im Ausland"}, {"id": "h", "text": "Verkaufen und Kaufen auf dem Marktplatz"}, {"id": "i", "text": "Sport am Morgen für alle"}, {"id": "j", "text": "Eine Reise mit Hund planen"}], "questions": [{"question_num": 1, "question_text": "Text A - Welche Überschrift passt?", "correct_answer": "d"}, {"question_num": 2, "question_text": "Text B - Welche Überschrift passt?", "correct_answer": "e"}, {"question_num": 3, "question_text": "Text C - Welche Überschrift passt?", "correct_answer": "h"}, {"question_num": 4, "question_text": "Text D - Welche Überschrift passt?", "correct_answer": "i"}, {"question_num": 5, "question_text": "Text E - Welche Überschrift passt?", "correct_answer": "b"}]}, {"aufgabe_num": 2, "typ": "multiple_choice", "text": "Thomas arbeitet seit drei Jahren in einem großen Fahrradgeschäft in München. Das Geschäft heißt \'Rad & Tat\' und liegt direkt im Zentrum der Stadt. Thomas mag seine Arbeit sehr, weil er selbst gern mit dem Fahrrad fährt und jeden Tag Kontakt mit vielen verschiedenen Menschen hat.\\n\\nSein Arbeitstag beginnt normalerweise um 9 Uhr morgens. Zuerst öffnet er die Werkstatt und kontrolliert den Computer. Dort sieht er, welche Fahrräder heute repariert werden müssen. Die meisten Kunden bringen ihre Räder schon früh vor der Arbeit vorbei. Thomas repariert kaputte Reifen, wechselt Bremsen aus oder baut neue Lichter an. Er findet diese praktische Arbeit gut, aber manchmal ist sie auch anstrengend, besonders im Frühling, wenn sehr viele Leute gleichzeitig ihr Fahrrad reparieren lassen wollen.\\n\\nAb 14 Uhr arbeitet Thomas im Verkauf. Er berät Kunden, die ein neues Fahrrad suchen. Er fragt sie, ob sie das Rad für den Weg zur Arbeit, für Sport oder für Touren in den Bergen brauchen. Das ist wichtig, damit er das passende Modell empfehlen kann. Letzte Woche hat Thomas einem älteren Ehepaar zwei moderne E-Bikes verkauft. Die beiden waren sehr zufrieden, weil er alles sehr ruhig und geduldig erklärt hat.\\n\\nUm 18 Uhr schließt das Geschäft. Bevor Thomas nach Hause geht, muss er noch die Kasse machen und aufräumen. Zweimal pro Woche macht er abends nach der Arbeit noch Sport. Er fährt dann mit seinen Kollegen eine große Runde durch den Park. Er sagt oft: \'Mein Hobby ist mein Beruf geworden und das ist ein großes Glück für mich.\'", "questions": [{"question_num": 6, "question_text": "Warum arbeitet Thomas gern im Fahrradgeschäft?", "options": ["a) Weil er im Zentrum von München wohnt.", "b) Weil er Radfahren mag und gerne Kontakt mit Menschen hat.", "c) Weil das Geschäft sehr groß ist."], "correct_answer": "b"}, {"question_num": 7, "question_text": "Was macht Thomas am Morgen als Erstes?", "options": ["a) Er repariert sofort das erste Fahrrad.", "b) Er öffnet die Werkstatt und kontrolliert den Computer.", "c) Er kauft neue Reifen und Bremsen."], "correct_answer": "b"}, {"question_num": 8, "question_text": "Wann ist die Arbeit in der Werkstatt besonders anstrengend?", "options": ["a) Im Frühling.", "b) Nur am Wochenende.", "c) Immer vor 9 Uhr morgens."], "correct_answer": "a"}, {"question_num": 9, "question_text": "Warum berät Thomas die Kunden im Verkauf?", "options": ["a) Damit er das passende Fahrradmodell für sie finden kann.", "b) Um ihnen zu zeigen, wie man ein E-Bike repariert.", "c) Weil die Kunden keine Touren in die Berge machen möchten."], "correct_answer": "a"}, {"question_num": 10, "question_text": "Was macht Thomas abends nach der Arbeit mit seinen Kollegen?", "options": ["a) Sie zählen gemeinsam das Geld in der Kasse.", "b) Sie fahren manchmal zusammen eine Runde mit dem Fahrrad.", "c) Sie reparieren im Park alte Fahrräder."], "correct_answer": "b"}]}, {"aufgabe_num": 3, "typ": "anzeigen", "anzeigen": [{"id": "a", "text": "Spanisch intensiv! Lernen Sie schnell Spanisch für den Beruf. Unser Kurs findet von Montag bis Freitag von 9:00 bis 13:00 Uhr statt. Perfekt für Personen mit flexiblen Arbeitszeiten."}, {"id": "b", "text": "Ihr Lieblingselement im Wohnzimmer ist alt oder beschädigt? Wir reparieren Ihre Polstermöbel und Sessel schnell und beziehen sie mit neuen Stoffen. Polsterei Service, Telefon: 48392."}, {"id": "c", "text": "Wochenendjob gesucht? Unser gemütliches Café in der Altstadt sucht für Samstag und Sonntag eine freundliche Servicekraft für den Verkauf. Erfahrung ist nicht nötig."}, {"id": "d", "text": "Fit im Park! Jeden Dienstag- und Donnerstagabend trainieren wir gemeinsam an der frischen Luft. Kein Studio, nur Natur und nette Leute im Team. Kommen Sie zum Probetraining!"}, {"id": "e", "text": "Sprachcafé am Samstagnachmittag! Sprechen Sie kostenlos Deutsch mit anderen netten Leuten bei Kaffee und Kuchen. Beginn ist um 15:00 Uhr im Bürgerhaus."}, {"id": "f", "text": "Gitarrenunterricht für Anfänger. Erfahrener Lehrer gibt Einzelstunden für Jung und Alt. Termine sind flexibel vereinbar, auch donnerstags am späten Abend ab 19 Uhr möglich."}, {"id": "g", "text": "Suche eine zuverlässige Babysitterin für meine Zwillinge (3 Jahre alt), immer montags und mittwochs von 10:00 bis 12:00 Uhr am Vormittag. Bezahle gut."}, {"id": "h", "text": "Schöne 3-Zimmer-Wohnung im Erdgeschoss zu vermieten. Die Wohnung hat eine große Terrasse und Zugang zu einem eigenen Gartenanteil. Ideal für Familien mit Kind."}, {"id": "i", "text": "Hausaufgabenhilfe nach der Schule! Ich hole Ihre Kinder (6-10 Jahre) von der Schule ab und helfe ihnen bei den Hausaufgaben. Dienstags und donnerstags von 14:00 bis 17:00 Uhr."}, {"id": "j", "text": "Motorrad-Reparatur zum kleinen Preis! Wir reparieren alle Marken direkt in unserer Werkstatt im Industriegebiet. Termine nach Absprache."}, {"id": "k", "text": "Luxus-Wellness an der Ostsee. Entspannen Sie sich in unserem großen Spa- und Wellnessbereich. 5-Sterne-Hotel ab 220 Euro pro Person und Nacht. Perfekt zum Abschalten."}, {"id": "l", "text": "Urlaub an der Ostsee: Kleine, preiswerte Ferienwohnung direkt hinter den Dünen (nur 50 Meter bis zum Sandstrand) für maximal 3 Personen ab sofort für eine Woche zu vermieten."}], "questions": [{"question_num": 11, "situation": "Anna sucht einen Intensivkurs Spanisch für ihren Beruf. Sie hat tagsüber Zeit.", "question_text": "Welche Anzeige passt?", "correct_answer": "a"}, {"question_num": 12, "situation": "Marco möchte aktiver werden, mag aber keine Fitnessstudios. Er möchte draußen an der frischen Luft trainieren.", "question_text": "Welche Anzeige passt?", "correct_answer": "d"}, {"question_num": 13, "situation": "Familie Weber besteht aus drei Personen. Sie suchen eine Wohnung im Erdgeschoss mit einer Terrasse oder einem Garten.", "question_text": "Welche Anzeige passt?", "correct_answer": "h"}, {"question_num": 14, "situation": "Julia möchte am Wochenende ihr Deutsch verbessern und sucht ein kostenloses Treffen mit anderen Menschen.", "question_text": "Welche Anzeige passt?", "correct_answer": "e"}, {"question_num": 15, "situation": "Herr Schmidt hat ein kaputtes Sofa. Er sucht jemanden, der es repariert und mit neuem Stoff bezieht.", "question_text": "Welche Anzeige passt?", "correct_answer": "b"}, {"question_num": 16, "situation": "Sarah sucht einen Nebenjob für Samstag und Sonntag in einem Café.", "question_text": "Welche Anzeige passt?", "correct_answer": "c"}, {"question_num": 17, "situation": "Peter möchte Gitarre spielen lernen. Er kann nur am Donnerstagabend ab 19 Uhr kommen.", "question_text": "Welche Anzeige passt?", "correct_answer": "f"}, {"question_num": 18, "situation": "Lukas sucht eine günstige Unterkunft für eine Woche Urlaub an der Ostsee direkt am Strand.", "question_text": "Welche Anzeige passt?", "correct_answer": "l"}, {"question_num": 19, "situation": "Eine berufstätige Mutter sucht jemanden, der ihre achtjährige Tochter nachmittags von der Schule abholt und betreut.", "question_text": "Welche Anzeige passt?", "correct_answer": "i"}, {"question_num": 20, "situation": "Michael möchte am Wochenende sein altes Auto verkaufen.", "question_text": "Welche Anzeige passt?", "correct_answer": "x"}]}], "total_questions": 15, "duration_minutes": 90}, "hoeren": {"aufgaben": [{"aufgabe_num": 1, "typ": "kurzgespraeche", "title": "Aufgabe 1", "instruction": "Sie hören fünf kurze Texte. Kreuzen Sie an: Sind die Aussagen richtig oder falsch? Sie hören jeden Text einmal.", "heard_times": 1, "preparation_seconds": 30, "topic": "Hausarbeit im Alltag", "conversations": [{"conv_num": 1, "sprecher": [{"name": "Frau Berger", "voice_id": "Aoede"}], "script_segments": [{"sprecher": "Frau Berger", "text": "Unter der Woche arbeite ich sehr viel in einem Büro. Deshalb habe ich von Montag bis Freitag fast keine Zeit für die Hausarbeit. Meine Wohnung putze ich immer am Samstagmorgen, das dauert meistens zwei Stunden. Danach kaufe ich für die ganze Woche ein. Am Sonntag möchte ich dann nur entspannen und gar nichts tun."}], "questions": [{"question_num": 1, "question_type": "richtig_falsch", "question_text": "Frau Berger putzt ihre Wohnung am Wochenende.", "correct_answer": "Richtig"}]}, {"conv_num": 2, "sprecher": [{"name": "Herr Koch", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Herr Koch", "text": "Für mich ist Kochen keine lästige Arbeit. Ich koche jeden Abend eine warme Mahlzeit, wenn ich von der Arbeit nach Hause komme. Beim Schneiden von Gemüse kann ich wunderbar entspannen und den Stress vom Tag vergessen. Meine Frau macht danach die Küche wieder sauber. Das ist unsere feste Vereinbarung."}], "questions": [{"question_num": 2, "question_type": "richtig_falsch", "question_text": "Herr Koch findet das Kochen nach der Arbeit stressig.", "correct_answer": "Falsch"}]}, {"conv_num": 3, "sprecher": [{"name": "Sarah", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Sarah", "text": "Ich wohne in einer Wohngemeinschaft mit drei anderen Studenten. Früher gab es bei uns oft Streit wegen dem Putzen. Jetzt haben wir einen festen Putzplan. Jeden Freitag putzen wir alle zusammen eine Stunde lang die ganze Wohnung. Das funktioniert sehr gut und danach trinken wir oft noch einen Kaffee zusammen."}], "questions": [{"question_num": 3, "question_type": "richtig_falsch", "question_text": "In Sarahs Wohngemeinschaft gibt es jetzt einen Plan für das Putzen.", "correct_answer": "Richtig"}]}, {"conv_num": 4, "sprecher": [{"name": "Herr Müller", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Herr Müller", "text": "Ich mache eigentlich fast jede Hausarbeit gerne, außer Bügeln. Hemden bügeln ist für mich wirklich schrecklich! Deshalb bringe ich meine Hemden jeden Montag zu einer kleinen Wäscherei in der Nähe von meinem Haus. Das kostet zwar ein bisschen Geld, aber ich spare dadurch viel Zeit und ärgere mich nicht mehr."}], "questions": [{"question_num": 4, "question_type": "richtig_falsch", "question_text": "Herr Müller bringt seine Hemden weg, weil er nicht selbst bügeln möchte.", "correct_answer": "Richtig"}]}, {"conv_num": 5, "sprecher": [{"name": "Frau Schmidt", "voice_id": "Aoede"}], "script_segments": [{"sprecher": "Frau Schmidt", "text": "Ich habe drei Kinder und eine große Wohnung. Bei uns zu Hause müssen alle mithelfen. Meine Kinder sind zwar noch jung, aber sie können schon einfache Aufgaben im Haushalt machen. Sie bringen zum Beispiel den Müll raus oder helfen mir beim Einkaufen. Mein Mann wäscht meistens das Geschirr ab."}], "questions": [{"question_num": 5, "question_type": "richtig_falsch", "question_text": "Frau Schmidt muss die ganze Hausarbeit alleine machen.", "correct_answer": "Falsch"}]}]}, {"aufgabe_num": 2, "typ": "gespraech", "title": "Aufgabe 2", "instruction": "Sie hören jetzt ein Gespräch. Kreuzen Sie an: Sind die Aussagen richtig oder falsch? Sie hören das Gespräch zweimal.", "heard_times": 2, "preparation_seconds": 60, "sprecher": [{"name": "Moderatorin", "voice_id": "Aoede"}, {"name": "Herr Becker", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Moderatorin", "text": "Guten Tag, liebe Hörerinnen und Hörer. Heute sprechen wir in unserer Sendung über das Projekt \'Gemeinsam im Garten\' in unserer Stadt. Mein Gast ist Herr Becker, der dieses Projekt vor einem Jahr gestartet hat. Herzlich willkommen, Herr Becker!"}, {"sprecher": "Herr Becker", "text": "Guten Tag und danke für die Einladung. Ich freue mich sehr, heute hier zu sein und über unseren Garten zu berichten."}, {"sprecher": "Moderatorin", "text": "Herr Becker, erklären Sie uns doch kurz: Was genau ist dieser Nachbarschaftsgarten?"}, {"sprecher": "Herr Becker", "text": "Das ist ein großes Stück Land direkt hinter dem Hauptbahnhof. Früher war dieser Platz leer und nicht sehr schön. Jetzt haben wir dort viele Blumen, Gemüse und auch Obst gepflanzt. Alle Leute aus dem Stadtteil dürfen dort vorbeikommen und kostenlos mitarbeiten."}, {"sprecher": "Moderatorin", "text": "Das klingt wunderbar. Wie ist diese Idee entstanden? Wollten Sie einfach einen schönen Garten in der Stadt haben?"}, {"sprecher": "Herr Becker", "text": "Das auch. Aber das wichtigste Ziel war, dass die Nachbarn aus dem Viertel sich besser kennenlernen. In einer großen Stadt leben viele Menschen sehr anonym und einsam. In unserem Garten arbeitet man zusammen an der frischen Luft und spricht miteinander. Das verbindet die Menschen."}, {"sprecher": "Moderatorin", "text": "Wer darf denn alles mitarbeiten? Braucht man dafür schon viel Erfahrung beim Gärtnern?"}, {"sprecher": "Herr Becker", "text": "Nein, überhaupt nicht. Jede Person ist willkommen, egal ob alt oder jung. Viele junge Menschen wissen heute gar nicht mehr, wie man Tomaten oder Kartoffeln anpflanzt. Ältere Menschen haben oft viel Erfahrung und zeigen den Jüngeren gerne, wie es geht. So lernen wir alle voneinander."}, {"sprecher": "Moderatorin", "text": "Und wer bezahlt die ganzen Pflanzen und die Gartengeräte? Das kostet doch sicher Geld."}, {"sprecher": "Herr Becker", "text": "Die Stadt hat uns geholfen und für das erste Jahr eine finanzielle Unterstützung gegeben. Den Rest bezahlen wir durch kleine Spenden von den Nachbarn oder wir bekommen alte Gartengeräte geschenkt, die andere Leute nicht mehr brauchen."}, {"sprecher": "Moderatorin", "text": "Und was passiert mit dem Gemüse und dem Obst, wenn es reif ist? Verkaufen Sie die Sachen auf dem Markt?"}, {"sprecher": "Herr Becker", "text": "Nein, wir verkaufen die Ernte nicht. Wer im Garten hilft, darf sich Gemüse und Obst kostenlos mit nach Hause nehmen. Letzte Woche hatten wir so viele reife Erdbeeren, dass wir ein großes Fest für alle Nachbarn gefeiert und zusammen Erdbeerkuchen gegessen haben."}, {"sprecher": "Moderatorin", "text": "Wann hat der Garten geöffnet? Kann man einfach so vorbeikommen?"}, {"sprecher": "Herr Becker", "text": "Der Garten hat keine festen Öffnungszeiten und es gibt auch keinen Zaun. Aber jeden Samstag ab zehn Uhr morgens treffen wir uns alle zum gemeinsamen Arbeiten. Nach der Arbeit essen wir dann oft zusammen auf der Wiese."}, {"sprecher": "Moderatorin", "text": "Gibt es schon Pläne für die Zukunft?"}, {"sprecher": "Herr Becker", "text": "Ja, wir möchten bald eigene Bienen im Garten haben, um Honig zu machen. Außerdem planen wir im kommenden Sommer ein kleines Musikkonzert auf unserer Wiese."}, {"sprecher": "Moderatorin", "text": "Das sind wirklich tolle Pläne! Vielen Dank für das interessante Gespräch, Herr Becker, und weiterhin viel Erfolg für Ihr Projekt."}, {"sprecher": "Herr Becker", "text": "Ich danke Ihnen."}], "questions": [{"question_num": 6, "question_type": "richtig_falsch", "question_text": "Der Nachbarschaftsgarten befindet sich in der Nähe des Bahnhofs.", "correct_answer": "Richtig"}, {"question_num": 7, "question_type": "richtig_falsch", "question_text": "Man muss eine Gebühr bezahlen, um im Garten arbeiten zu dürfen.", "correct_answer": "Falsch"}, {"question_num": 8, "question_type": "richtig_falsch", "thought": "The main goal was that neighbors get to know each other.", "question_text": "Das Hauptziel des Projekts war der Kontakt zwischen den Nachbarn.", "correct_answer": "Richtig"}, {"question_num": 9, "question_type": "richtig_falsch", "question_text": "Nur Personen mit viel Erfahrung im Gärtnern dürfen mitmachen.", "correct_answer": "Falsch"}, {"question_num": 10, "question_type": "richtig_falsch", "question_text": "Ältere Menschen im Garten geben ihr Wissen an jüngere Menschen weiter.", "correct_answer": "Richtig"}, {"question_num": 11, "question_type": "richtig_falsch", "question_text": "Die Stadt bezahlt auch in Zukunft alle Kosten für das Projekt.", "correct_answer": "Falsch"}, {"question_num": 12, "question_type": "richtig_falsch", "question_text": "Die Nachbarn verkaufen das geerntete Gemüse, um Geld zu verdienen.", "correct_answer": "Falsch"}, {"question_num": 13, "question_type": "richtig_falsch", "question_text": "Vor kurzem gab es im Garten ein Fest mit Erdbeeren.", "correct_answer": "Richtig"}, {"question_num": 14, "question_type": "richtig_falsch", "question_text": "Jeden Samstag treffen sich die Nachbarn um zehn Uhr zum Arbeiten.", "correct_answer": "Richtig"}, {"question_num": 15, "question_type": "richtig_falsch", "question_text": "Herr Becker möchte im Sommer ein Konzert im Garten organisieren.", "correct_answer": "Richtig"}]}, {"aufgabe_num": 3, "typ": "ansagen", "title": "Aufgabe 3", "instruction": "Sie hören fünf kurze Texte aus dem Radio und anderen Medien. Kreuzen Sie an: Sind die Aussagen richtig oder falsch? Sie hören jeden Text zweimal.", "heard_times": 2, "preparation_seconds": 30, "ansagen": [{"ansage_num": 1, "sprecher": "Ansagerin", "voice_id": "Aoede", "text": "Achtung an Gleis 4! Der Regional-Express nach München, geplante Abfahrt um 14 Uhr 15, hat heute wegen einer technischen Störung circa fünfzehn Minuten Verspätung. Reisende nach München werden gebeten, auch den Zug auf Gleis 5 zu nutzen. Dieser fährt pünktlich anstelle des Regional-Expresses ab.", "question_num": 16, "question_type": "richtig_falsch", "question_text": "Der Zug nach München um 14 Uhr 15 fährt heute später ab.", "correct_answer": "Richtig"}, {"ansage_num": 2, "sprecher": "Ansager", "voice_id": "Charon", "text": "Guten Tag, hier ist die Arztpraxis von Dr. Martin Schmidt. Unsere Praxis bleibt wegen Urlaub vom ersten bis zum zehnten August geschlossen. In dringenden Krankheitsfällen wenden Sie sich bitte an die Praxis von Frau Dr. Müller in der Hauptstraße 4. Ab dem elften August sind wir wieder wie gewohnt für Sie da.", "question_num": 17, "question_type": "richtig_falsch", "question_text": "Die Praxis von Dr. Schmidt ist den ganzen Monat August geschlossen.", "correct_answer": "Falsch"}, {"ansage_num": 3, "sprecher": "Ansagerin", "voice_id": "Aoede", "text": "Und hier das Wetter für morgen Donnerstag. Nach einem nebligen Morgen wird es am Nachmittag überall in der Region sonnig und warm mit Temperaturen bis zu 25 Grad. Erst am späten Abend kann es im Süden leichte Regenschauer geben. Freuen Sie sich also auf einen schönen, warmen Nachmittag!", "question_num": 18, "question_type": "richtig_falsch", "question_text": "Morgen Nachmittag wird das Wetter in der Region schön und sonnig.", "correct_answer": "Richtig"}, {"ansage_num": 4, "sprecher": "Ansager", "voice_id": "Charon", "text": "Liebe Kundinnen und Kunden, beachten Sie unsere Sonderangebote am heutigen Freitag! Besuchen Sie unsere große Gemüseabteilung im ersten Stock. Nur heute bieten wir Ihnen frische, süße Bio-Äpfel aus der Region für nur zwei Euro das Kilo an. Unseren Kundenservice finden Sie direkt im Erdgeschoss neben den Kassen.", "question_num": 19, "question_type": "richtig_falsch", "question_text": "Die billigen Bio-Äpfel stehen heute im Erdgeschoss.", "correct_answer": "Falsch"}, {"ansage_num": 5, "sprecher": "Ansagerin", "voice_id": "Aoede", "text": "Herzlich willkommen im Stadtmuseum. Bitte beachten Sie unsere geänderten Öffnungszeiten am kommenden Wochenende. Am Samstag und am Sonntag haben wir für unsere Besucher statt bis 18 Uhr neu bis 20 Uhr geöffnet. Der Eintritt für Kinder unter zwölf Jahren ist an beiden Tagen wie immer kostenlos.", "question_num": 20, "question_type": "richtig_falsch", "question_text": "Das Stadtmuseum schließt am Wochenende zwei Stunden später als gewöhnlich.", "correct_answer": "Richtig"}]}], "total_questions": 15, "duration_minutes": 30}, "sprachbausteine": {"aufgaben": [{"aufgabe_num": 1, "typ": "lueckentext_mc", "text_with_gaps": "Lieber Thomas,\\n\\nwie geht es dir? Ich hoffe, alles ist gut bei dir und du hast nicht so viel Stress bei der Arbeit. Ich wohne jetzt {21} drei Wochen in meiner neuen Wohnung und sie {22} mir wirklich sehr gut. Ich habe mich für diese Wohnung entschieden, {23} sie sehr hell ist und einen schönen Balkon {24} einem tollen Blick auf den Park hat. Auch die Lage ist perfekt, denn ich kann in zehn Minuten zu Fuß zum Bahnhof gehen.\\n\\nDie Nachbarn, {25} im Haus wohnen, sind auch sehr nett. Letzte Woche hat mir ein Nachbar sogar beim Tragen von schweren Kartons geholfen. Das war wirklich ein großes Glück!\\n\\nAm nächsten Samstag möchte ich meinen Einzug endlich ein bisschen feiern. Ich hoffe sehr, {26} du Zeit hast und mich in meiner neuen Wohnung {27}. Es gibt leckeres Essen vom Grill, frische Salate und kalte Getränke. Du {28} natürlich auch gerne deine Schwester mitbringen, ich kenne sie ja bereits aus dem Urlaub.\\n\\nDie Party beginnt {29} 18 Uhr. Bitte sag mir bis Donnerstag Bescheid, ob du Zeit hast, damit ich das Essen gut planen kann. Ich freue mich schon sehr {30} dich!\\n\\nViele Grüße,\\nMarkus", "options": [{"question_num": 21, "a": "seit", "b": "vor", "c": "für", "correct_answer": "a"}, {"question_num": 22, "a": "gefallen", "b": "gefällt", "c": "gefallt", "correct_answer": "b"}, {"question_num": 23, "a": "weil", "b": "denn", "c": "obwohl", "correct_answer": "a"}, {"question_num": 24, "a": "mit", "b": "bei", "c": "von", "correct_answer": "a"}, {"question_num": 25, "a": "die", "b": "der", "c": "denen", "correct_answer": "a"}, {"question_num": 26, "a": "dass", "b": "ob", "c": "weil", "correct_answer": "a"}, {"question_num": 27, "a": "besuchst", "b": "besuchen", "c": "besucht", "correct_answer": "a"}, {"question_num": 28, "a": "kannst", "b": "musst", "c": "sollst", "correct_answer": "a"}, {"question_num": 29, "a": "um", "b": "am", "c": "an", "correct_answer": "a"}, {"question_num": 30, "a": "auf", "b": "für", "c": "über", "correct_answer": "a"}]}, {"aufgabe_num": 2, "typ": "lueckentext_wortbank", "text_with_gaps": "Sehr geehrte Bewohnerinnen und Bewohner,\\n\\nwir möchten Sie heute schriftlich darüber informieren, dass in der nächsten Woche einige wichtige Arbeiten an unserem {31} stattfinden werden. Die Firma Schmidt hat den Auftrag erhalten, die alten Fenster im Treppenhaus durch neue Holzfenster zu {32}.\\n\\nDie Bauarbeiten beginnen bereits am {33} und dauern voraussichtlich bis zum darauffolgenden Freitag. In dieser Zeit kann es tagsüber zwischen 8:00 und 16:00 Uhr zu erheblichem Lärm und Schmutz im Haus kommen. Wir bitten Sie deshalb vielmals um Entschuldigung und um Ihr {34}.\\n\\nBitte achten Sie unbedingt darauf, dass alle Fluchtwege und Gänge im Treppenhaus frei bleiben, damit die Handwerker die neuen Fenster sicher {35} können. Wenn Sie dort einen Kinderwagen oder ein {36} geparkt haben, bringen Sie diese Sachen bitte für diese Tage im Fahrradkeller unter.\\n\\nAm kommenden Donnerstag wird außerdem der Aufzug wegen Wartungsarbeiten für einige Stunden komplett {37} sein. Falls Sie schwere Einkäufe oder Möbel transportieren müssen, planen Sie dies bitte vor diesem neuen {38}.\\n\\nWir versprechen Ihnen, die Störungen im Alltag so {39} wie möglich zu halten. Bei dringenden Fragen oder Problemen können Sie sich gerne an unser {40} wenden.\\n\\nMit freundlichen Grüßen,\\nIhre Hausverwaltung Müller", "wortbank": [{"id": "a", "word": "BÜRO"}, {"id": "b", "word": "ERLAUBNIS"}, {"id": "c", "word": "ERSETZEN"}, {"id": "d", "word": "FAHRRAD"}, {"id": "e", "word": "GEBÄUDE"}, {"id": "f", "word": "GERING"}, {"id": "g", "word": "GESPERRT"}, {"id": "h", "word": "MONTAG"}, {"id": "i", "word": "OFFEN"}, {"id": "j", "word": "REPARIEREN"}, {"id": "k", "word": "SCHNELL"}, {"id": "l", "word": "TERMIN"}, {"id": "m", "word": "TRANSPORTIEREN"}, {"id": "n", "word": "VERSTÄNDNIS"}, {"id": "o", "word": "WOHNUNG"}], "options": [{"question_num": 31, "correct_answer": "e"}, {"question_num": 32, "correct_answer": "c"}, {"question_num": 33, "correct_answer": "h"}, {"question_num": 34, "correct_answer": "n"}, {"question_num": 35, "correct_answer": "m"}, {"question_num": 36, "correct_answer": "d"}, {"question_num": 37, "correct_answer": "g"}, {"question_num": 38, "correct_answer": "l"}, {"question_num": 39, "correct_answer": "f"}, {"question_num": 40, "correct_answer": "a"}]}], "total_questions": 20, "duration_minutes": 30}, "schreiben": {"total_time_minutes": 30, "aufgaben": [{"aufgabe_num": 1, "aufgabe_typ": "brief_email", "aufgabe": "Sie haben eine E-Mail von Ihrer Freundin / Ihrem Freund bekommen. Sie/Er bittet Sie um Hilfe oder Rat zu einem alltäglichen Thema (Umzug, Reise oder Freizeitaktivität). Schreiben Sie eine Antwort-E-Mail.\\nSchreiben Sie zu allen drei Punkten:\\n- ob und wie Sie helfen können\\n- wann Sie Zeit haben\\n- ein konkreter Vorschlag", "min_words": 80, "max_words": 130}]}, "sprechen": {"total_time_minutes": 15, "vorbereitungszeit_minutes": 20, "teile": [{"teil_num": 1, "titel": "Einander kennenlernen", "instructions": "Stellen Sie sich vor und beantworten Sie die Fragen des Prüfers.", "themen": ["Name", "Herkunft", "Wohnsituation", "Beruf/Studium", "Deutschlernen", "Hobbys"], "fragen": [{"frage_num": 1, "frage_text": "[warm] Guten Tag! Willkommen. Wie heißen Sie und woher kommen Sie?", "needs_audio": true}, {"frage_num": 2, "frage_text": "Was machen Sie beruflich oder studieren Sie gerade?", "needs_audio": true}, {"frage_num": 3, "frage_text": "Wie lange lernen Sie schon Deutsch und warum?", "needs_audio": true}, {"frage_num": 4, "frage_text": "Was machen Sie in Ihrer Freizeit?", "needs_audio": true}]}, {"teil_num": 2, "titel": "Uber ein Thema sprechen", "instructions": "Jede Person hat einen kurzen Text zum Thema \\"Homeoffice\\" gelesen. Stellen Sie Ihre Meinung vor und diskutieren Sie dann gemeinsam.", "thema": "Homeoffice", "meinungen": [{"person": "A", "zitat": "\\"Ich finde Homeoffice sehr positiv, weil man flexibler und produktiver ist.\\""}, {"person": "B", "zitat": "\\"Ich sehe Homeoffice kritisch - die Grenzen zwischen Arbeit und Freizeit verschwimmen.\\""}], "fragen": [{"frage_num": 5, "frage_text": "Was haben Sie uber Homeoffice gelesen? Stellen Sie Ihre Meinung vor.", "needs_audio": true}, {"frage_num": 6, "frage_text": "Was denken Sie - welche Meinung uberzeugt mehr?", "needs_audio": true}, {"frage_num": 7, "frage_text": "Haben Sie eigene Erfahrungen mit diesem Thema?", "needs_audio": true}]}, {"teil_num": 3, "titel": "Gemeinsam etwas planen", "instructions": "Planen Sie gemeinsam eine Veranstaltung fur Ihre Sprachschule.", "szenario": "Ihre Sprachschule mochte ein Sommerfest fur alle Teilnehmer organisieren.", "planungspunkte": ["Wann und wo?", "Programm und Aktivitaten", "Essen und Getranke", "Aufgabenverteilung"], "fragen": [{"frage_num": 8, "frage_text": "Wann und wo soll das Fest stattfinden? Was schlagen Sie vor?", "needs_audio": true}, {"frage_num": 9, "frage_text": "Was soll auf dem Programm stehen?", "needs_audio": true}, {"frage_num": 10, "frage_text": "Wer ubernimmt welche Aufgaben fur das Fest?", "needs_audio": true}]}]}, "status": "pending_audio", "telc_level": "B1", "exam_type": "telc", "pathway": "telc_b1", "audio_progress": 0}')

def get_telc_b2_ai_seed():
    return json.loads('{"exam_id": "exam_telc_b2_001", "title": "TELC Deutsch B2 - Übungstest 1 (KI-generiert)", "lesen": {"aufgaben": [{"aufgabe_num": 1, "typ": "zuordnung", "short_texts": [{"id": "A", "text": "Die Dezentralisierung der Energiegewinnung gilt als tragende Säule der nationalen Nachhaltigkeitsstrategie. Indem das Monopol der großen Energiekonzerne durch genossenschaftlich organisierte Solarparks und lokale Windkraftanlagen aufgebrochen wird, leistet die Bevölkerung einen aktiven Beitrag zum Klimaschutz. Allerdings stößt die Umsetzung vor Ort oft auf bürokratische Hürden, da die Netzinfrastruktur veraltet ist und Genehmigungsverfahren sich über Jahre hinwegziehen. Dennoch zeigt das wachsende Engagement der Bürgerinitiativen, dass die Bereitschaft zur Eigeninitiative hoch ist, sofern die rechtlichen Rahmenbedingungen vereinfacht würden."}, {"id": "B", "text": "Überall fordern Unternehmen von ihren Arbeitskräften kontinuierliche Anpassung und lebenslanges Lernen. Gleichzeitig zeigt sich in der Praxis jedoch eine gravierende Diskrepanz: Während anspruchsvolle Schulungsprogramme offiziell bereitgestellt und gefördert werden, bleibt der alltägliche Arbeitsdruck unvermindert hoch. Viele Angestellte berichten, dass ihnen schlichtweg die zeitlichen Ressourcen fehlen, um das Gelernte effektiv im Arbeitsalltag umzusetzen, wodurch wertvolles Potenzial ungenutzt verpufft. Eine Reduzierung des Arbeitspensums während solcher Qualifizierungsmaßnahmen wird von Arbeitgebern indessen nur in Ausnahmefällen gewährt."}, {"id": "C", "text": "Angesichts der rasant fortschreitenden Erderwärmung und der damit einhergehenden Zunahme von Extremwetterereignissen stehen Kommunen vor immensen Herausforderungen. Das städtebauliche Konzept der sogenannten Schwammstadt rückt hierbei zunehmend in den Mittelpunkt des Interesses. Ziel ist es, anfallendes Regenwasser nicht ungenutzt in die Kanalisation abzuleiten, sondern es wie ein Schwamm in Grünflächen, Dachgärten und speziellen Speicherbecken aufzufangen. Dadurch können urbane Hitzeinseln effektiv abgekühlt und das Risiko von Sturzfluten bei Starkregen drastisch minimiert werden."}, {"id": "D", "text": "Die Flut an digitalen Informationen erfordert eine grundlegende Neuausrichtung unseres Bildungssystems. Um die heranwachsende Generation vor manipulativen Desinformationskampagnen zu schützen, reicht das bloße Erlernen technischer Fertigkeiten längst nicht mehr aus. Vielmehr muss im Unterricht eine tiefgehende Medienkompetenz verankert werden, die Schülerinnen und Schüler dazu befähigt, Quellen kritisch zu hinterfragen und verlässliche Berichterstattung von gezielter Propaganda zu unterscheiden. Nur so kann gewährleistet werden, dass die demokratische Diskursfähigkeit auch im digitalen Raum stabil bleibt."}, {"id": "E", "text": "Zahlreiche Großkonzerne schmücken sich medienwirksam mit Diversitätskampagnen, um ihr Image als weltoffene Arbeitgeber aufzupolieren. Kritiker weisen jedoch darauf hin, dass diese Maßnahmen oft an der Oberfläche verharren und als reines Marketinginstrument dienen. Solange traditionelle Führungsstrukturen unangetastet bleiben und Minderheiten lediglich als symbolische Repräsentanten ohne echten Einfluss fungieren, kann von einer echten Chancengleichheit keine Rede sein. Eine nachhaltige Unternehmenskultur erfordert einen tiefgreifenden mentalen Wandel auf sämtlichen Führungsebenen."}], "ueberschriften": [{"id": "a", "text": "Die Herausforderung der dezentralen Energieerzeugung und der Beitrag der Bürgerinnen und Bürger."}, {"id": "b", "text": "Warum Weiterbildungsmaßnahmen trotz hoher Motivation oft an Arbeitsbelastungen scheitern."}, {"id": "c", "text": "Urbane Klimaanpassung: Das Konzept der wasserspeichernden Metropole."}, {"id": "d", "text": "Schulische Medienkompetenz als Abwehrbollwerk gegen Desinformation im digitalen Zeitalter."}, {"id": "e", "text": "Struktureller Wandel statt bloßer Symbolpolitik: Echte Vielfalt in der Unternehmensphilosophie."}, {"id": "f", "text": "Die ökonomischen Gewinne durch den globalen Ausbau erneuerbarer Energiequellen."}, {"id": "g", "text": "Wie künstliche Intelligenz den traditionellen Bildungsweg in Schulen vollständig ablösen wird."}, {"id": "h", "text": "Der Fachkräftemangel in der Bauwirtschaft behindert die Modernisierung der Innenstädte."}, {"id": "i", "text": "Lebenslanges Lernen als exklusives Privileg hochqualifizierter Führungskräfte."}, {"id": "j", "text": "Die zunehmende Bedeutung von Remote-Arbeit im internationalen Dienstleistungssektor."}], "questions": [{"question_num": 1, "question_text": "Welche Überschrift passt zu Text A?", "correct_answer": "a"}, {"question_num": 2, "question_text": "Welche Überschrift passt zu Text B?", "correct_answer": "b"}, {"question_num": 3, "question_text": "Welche Überschrift passt zu Text C?", "correct_answer": "c"}, {"question_num": 4, "question_text": "Welche Überschrift passt zu Text D?", "correct_answer": "d"}, {"question_num": 5, "question_text": "Welche Überschrift passt zu Text E?", "correct_answer": "e"}]}, {"aufgabe_num": 2, "typ": "multiple_choice", "text": "Die fortschreitende Digitalisierung hat die traditionelle Bürostruktur grundlegend erschüttert. Während das Konzept der ortsunabhängigen Arbeit, gemeinhin als Homeoffice bezeichnet, anfangs als ultimativer Befreiungsschlag für die Work-Life-Balance gefeiert wurde, offenbaren sich bei genauerer Betrachtung erhebliche psychologische Risiken. Eine zentrale Rolle spielt dabei die sogenannte Entgrenzung, also das allmähliche Verschwimmen der Trennlinie zwischen Berufs- und Privatleben. Wenn der physische Arbeitsweg wegfällt und der Küchentisch zum Schreibtisch mutiert, wird es für Beschäftigte zunehmend schwieriger, gedanklich vom Job Abstand zu nehmen. Dies führt paradoxerweise dazu, dass im Homeoffice häufig unbezahlte Mehrarbeit geleistet wird, da die Erreichbarkeit rund um die Uhr als ungeschriebene Erwartungshaltung wahrgenommen wird.\\n\\nExperten weisen darauf hin, dass die vermeintlich hinzugewonnene Autonomie oft mit einem Gefühl der sozialen Isolation einhergeht. Der informelle Austausch an der Kaffeemaschine, welcher für die psychische Stabilität und den innerbetrieblichen Zusammenhalt von unschätzbarem Wert ist, lässt sich durch virtuelle Meetings kaum rekonstruieren. Zudem neigen viele Arbeitgeber dazu, den vermeintlichen Kontrollverlust durch digitale Überwachungssysteme zu kompensieren. Dies wiederum untergräbt das Vertrauensverhältnis nachhaltig und erzeugt bei den Angestellten einen permanenten Leistungsdruck. Würde man die Arbeitsbedingungen nicht drastisch reformieren, so prognostizieren Soziologen, könnte die psychische Erschöpfung breiter Bevölkerungsschichten massiv zunehmen.\\n\\nÜberdies zeigen Untersuchungen zur Arbeitspsychologie, dass das Fehlen eines klaren Feedbacks im virtuellen Raum oft zu tiefen Verunsicherungen führt. Während im direkten Face-to-Face-Kontakt unausgesprochene Signale wie Körpersprache oder Tonfall beruhigend oder klärend wirken können, bleibt in der digitalen Kommunikation viel Raum für Fehlinterpretationen. Die von manchen Arbeitnehmern ersehnte Isolation entpuppt sich nicht selten als Katalysator für Versagensängste. Es wäre daher fahrlässig, die Verantwortung für die mentale Gesundheit ausschließlich auf das Individuum abzuwälzen. Vielmehr müssen Organisationen Konzepte der „virtuellen Fürsorge“ entwickeln, bei denen Führungskräfte gezielt geschult werden, feine Nuancen der Überlastung auch über Bildschirme hinweg zu dekodieren.\\n\\nUm diesen negativen Tendenzen entgegenzuwirken, bedarf es einer klaren Reglementierung. Sowohl rechtliche Rahmenbedingungen als auch eine veränderte Führungskultur sind erforderlich, um das Recht auf Nichterreichbarkeit durchzusetzen. Einige zukunftsorientierte Unternehmen haben bereits strenge Serverabschaltungen nach Feierabend etabliert, wohingegen andere noch immer auf die bedingungslose Eigenverantwortung der Angestellten setzen. Letzteres erweist sich jedoch häufig als Trugschluss, da der Druck des Marktes die individuelle Belastungsgrenze meist überschreitet. Es zeigt sich somit, dass die Transformation der Arbeitswelt nur dann gelingen kann, wenn der Gesundheitsschutz der Arbeitnehmer konsequent im Mittelpunkt aller Digitalisierungsmaßnahmen steht.", "questions": [{"question_num": 6, "question_text": "Was ist laut Text eine der Hauptursachen für unbezahlte Mehrarbeit im Homeoffice?", "options": ["a) Die fehlende Regulierung der täglichen Arbeitszeit durch staatliche Behörden.", "b) Die gefühlte Erwartung, ständig für den Arbeitgeber erreichbar sein zu müssen.", "c) Eine unzureichende Ausstattung des häuslichen Arbeitsplatzes mit moderner Technologie."], "correct_answer": "b"}, {"question_num": 7, "question_text": "Welche Auswirkung hat der Mangel an informellen Gesprächen am Arbeitsplatz?", "options": ["a) Er stärkt die Fokussierung auf die eigentlichen Kernaufgaben des Betriebs.", "b) Er führt langfristig zu einer Reduzierung der digitalen Überwachungsmaßnahmen.", "c) Er gefährdet das psychische Wohlbefinden sowie das Zusammengehörigkeitsgefühl der Belegschaft."], "correct_answer": "c"}, {"question_num": 8, "question_text": "Wie bewertet der Autor die Maßnahme betroffener Unternehmen, auf die reine Eigenverantwortung der Mitarbeiter zu setzen?", "options": ["a) Als ineffektiven Lösungsansatz, da marktwirtschaftliche Zwänge die individuellen Grenzen oft überschreiten.", "b) Als fortschrittliches Konzept, das die persönliche Autonomie der Beschäftigten optimal fördert.", "c) Als notwendige Übergangsphase, bis gesetzliche Pausenregelungen endgültig verabschiedet sind."], "correct_answer": "a"}, {"question_num": 9, "question_text": "Was lässt sich aus dem Text über den Einsatz digitaler Überwachungssysteme durch Arbeitgeber schließen?", "options": ["a) Sie steigert nachweislich die Arbeitseffizienz im Homeoffice um ein Vielfaches.", "b) Sie resultiert aus dem gefühlten Kontrollverlust der Arbeitgeber und schädigt das Arbeitsklima.", "c) Sie stellt eine gesetzlich vorgeschriebene Sicherheitsmaßnahme dar."], "correct_answer": "b"}, {"question_num": 10, "question_text": "Welche Rolle spielt die digitale Kommunikation im Hinblick auf Arbeitsängste?", "options": ["a) Digitale Schnittstellen reduzieren Missverständnisse durch schriftlich präzise Dokumentation aller Vorgänge.", "b) Das Fehlen nonverbaler Signale in der Online-Interaktion begünstigt Fehlinterpretationen und Verunsicherung.", "c) Sie erfordert eine intensivere Schulung der Software-Entwickler zur Verminderung technischer Barrieren."], "correct_answer": "b"}]}, {"aufgabe_num": 3, "typ": "anzeigen", "anzeigen": [{"id": "a", "text": "Akademie Digitale Wirtschaft: Fortbildung für erfahrene Projektmanager im Bereich des agilen Arbeitens (Scrum, Kanban). Voraussetzung: Mindestens 2 Jahre nachweisbare Berufserfahrung im IT-Sektor."}, {"id": "b", "text": "KlimaConsulting: Beratung zur energetischen Sanierung von denkmalgeschützten Gewerbeimmobilien und alten Industrieanlagen. Keine Beratung für private Wohngebäude."}, {"id": "c", "text": "Sprachenzentrum Nord: Deutschkurse für ausländische medizinische Fachkräfte (C1 Medizin). Einstieg nur möglich für bereits approbierte oder praktizierende Ärzte mit ausländischem Diplom."}, {"id": "d", "text": "KreativRaum: Vermietung von voll ausgestatteten Co-Working-Spaces für Grafiker, Architekten und Produktdesigner inklusive 3D-Druck-Infrastruktur. Nur Langzeitmiete (Mindestvertragslaufzeit 6 Monate)."}, {"id": "e", "text": "Recht & Gesetz: Wochenend-Fortbildungsseminar für HR-Verantwortliche und Personalprüfer zum neuen Arbeitszeitgesetz und Homeoffice-Regelungen. Termin: Ausschließlich samstags im November."}, {"id": "f", "text": "EcoEco: Finanzierungsberatung und Fördermittelakquise für nachhaltige Start-ups und Social-Entrepreneurship-Initiativen. Wir unterstützen Sie bei der Beantragung komplexer EU-Subventionen."}, {"id": "g", "text": "Wissenschaft vor Ort: Intensiver Abendlehrgang für Statitiskauswertung mit R und Python für Sozial- und Geisteswissenschaftler. Mathematische Vorkenntnisse auf Universitätsniveau zwingend erforderlich."}, {"id": "h", "text": "Mediationsbüro Weise: Konfliktmanagement, Mediation und Deeskalationstraining für Teams im öffentlichen Dienst (Behörden, Ämter, Verwaltungen). Mindestteilnehmerzahl: 8 Personen."}, {"id": "i", "text": "Uni-Sport & Gesundheit: Präventionskurse für ergonomische Rückengesundheit am Arbeitsplatz, speziell konzipiert für langjährige Schreibtischtätigkeiten. Vollständige Übernahme der Kosten durch gesetzliche Krankenkassen möglich."}, {"id": "j", "text": "TechStartup Hub: Vermietung von flexiblen Tages- und Wochenpässen für Co-Working ohne jegliche Mindestvertragslaufzeit. Ideal für freiberufliche Texter, Übersetzer und Webdesigner."}, {"id": "k", "text": "Global Trade Consulting: Spezialisierte Beratung für Zollrecht und Exportbeschränkungen im asiatischen Raum für bereits etablierte mittelständische Industrieunternehmen."}, {"id": "l", "text": "Bildung Express: Intensives B2-Deutschtraining für Logistikfachkräfte, Schwerpunkt Lagerlogistik, kommissionierungsrelevante Vokabeln und internationale Versandabwicklung."}], "questions": [{"question_num": 11, "situation": "Sarah ist freiberufliche Webdesignerin und sucht einen flexiblen Arbeitsplatz, den sie wochenweise mieten kann, um ein kurzfristiges Kundenprojekt ohne lange Vertragsbindung zu bearbeiten.", "question_text": "Welche Anzeige passt?", "correct_answer": "j"}, {"question_num": 12, "situation": "Dr. Al-Mansour hat sein Medizinstudium an einer Universität in Ägypten erfolgreich abgeschlossen und sucht einen gezielten Fachsprachkurs zur Bewältigung der Fachsprachprüfung an deutschen Krankenhäusern.", "question_text": "Welche Anzeige passt?", "correct_answer": "c"}, {"question_num": 13, "situation": "Felix berät gewerbliche Betriebe bei Sanierungsarbeiten. Aktuell sucht er professionelle Beratung speziell für die energetische Modernisierung eines alten, unter historischem Denkmalschutz stehenden Fabrikgebäudes.", "question_text": "Welche Anzeige passt?", "correct_answer": "b"}, {"question_num": 14, "situation": "Eine Abteilungsleiterin in einer städtischen Behörde sucht für ihr zerstrittenes, 10-köpfiges Amtskollegium ein maßgeschneidertes Deeskalations- und Konfliktlösungstraining.", "question_text": "Welche Anzeige passt?", "correct_answer": "h"}, {"question_num": 15, "situation": "Ein studentischer Politikwissenschaftler mit soliden Unimathe-Kenntnissen möchte für seine Masterarbeit empirische Daten auswerten und sucht einen Abendkurs erlernbarer Programmiersprachen wie Python.", "question_text": "Welche Anzeige passt?", "correct_answer": "g"}, {"question_num": 16, "situation": "Thomas, Gründer eines neu geschaffenen umweltfreundlichen Logistik-Startups, sucht finanzielle Unterstützung sowie spezialisierte Beratung bei der Beantragung staatlicher und europäischer Subventionen.", "question_text": "Welche Anzeige passt?", "correct_answer": "f"}, {"question_num": 17, "situation": "Eine HR-Führungskraft möchte sich an einem Samstag im Spätherbst über die aktuelle rechtliche Lage bezüglich gesetzlicher Arbeitszeitregelungen und Telearbeit weiterbilden.", "question_text": "Welche Anzeige passt?", "correct_answer": "e"}, {"question_num": 18, "situation": "Michael hat Geisteswissenschaften studiert, arbeitet seit einem Jahr als Quereinsteiger im Marketing und möchte eine qualifizierte Zertifizierung zum agilen Projektmanager (Scrum) erwerben.", "question_text": "Welche Anzeige passt?", "correct_answer": "x"}, {"question_num": 19, "situation": "Anna arbeitet im Bereich der Logistik und möchte einen Deutschkurs zur B2-Stufe machen, um spezifische Begriffe zur Warenkommissionierung und Versandabfertigung zu lernen.", "question_text": "Welche Anzeige passt?", "correct_answer": "l"}, {"question_num": 20, "situation": "Ein kleines, inhabergeführtes Modegeschäft sucht ein Seminar zur Schulung seiner Mitarbeiter für den kundenorientierten Verkauf von fair gehandelter Kleidung.", "question_text": "Welche Anzeige passt?", "correct_answer": "x"}]}], "total_questions": 15, "duration_minutes": 90}, "hoeren": {"aufgaben": [{"aufgabe_num": 1, "typ": "kurzgespraeche", "title": "Aufgabe 1", "instruction": "Sie hören fünf kurze Texte. Kreuzen Sie an: Sind die Aussagen richtig oder falsch? Sie hören jeden Text einmal.", "heard_times": 1, "preparation_seconds": 30, "topic": "Digitalisierung am Arbeitsplatz und die Einführung Künstlicher Intelligenz", "conversations": [{"conv_num": 1, "sprecher": [{"name": "Frau Brand", "voice_id": "Aoede"}], "script_segments": [{"sprecher": "Frau Brand", "text": "Wenn ich die Debatte um die künstliche Intelligenz in unserem Großraumbüro verfolge, überkommt mich eine gewisse Skepsis. Zwar erleichtert das neue System die automatisierte Datenanalyse erheblich, sodass wir wertvolle Arbeitszeit einsparen. Dennoch befürchte ich, dass die zwischenmenschliche Dynamik im Team, die für kreative Prozesse essenziell ist, durch die ständige Interaktion mit Maschinen verkümmern könnte."}], "questions": [{"question_num": 1, "question_type": "richtig_falsch", "question_text": "Frau Brand befürchtet keineswegs den Verlust menschlicher Nähe im Berufsleben infolge der Digitalisierung.", "correct_answer": "Falsch"}]}, {"conv_num": 2, "sprecher": [{"name": "Herr Krause", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Herr Krause", "text": "Die Umstellung auf die neue digitale Plattform sollte eigentlich unsere Arbeitsabläufe optimieren, doch das Gegenteil ist derzeit der Fall. Ohne eine fundierte Einführung wurden wir ins kalte Wasser geworfen, wobei komplexe Fehlermeldungen den Alltag blockieren. Hätte man uns eine adäquate technische Unterstützung zur Seite gestellt, wäre die Frustration im Kollegium sicherlich vermeidbar gewesen."}], "questions": [{"question_num": 2, "question_type": "richtig_falsch", "question_text": "Herr Krause ist der Ansicht, dass die Umstellung auf neue Technologien durch eine unzureichende Betreuung erschwert wird.", "correct_answer": "Richtig"}]}, {"conv_num": 3, "sprecher": [{"name": "Frau Dr. Al-Mansoori", "voice_id": "Aoede"}], "script_segments": [{"sprecher": "Frau Dr. Al-Mansoori", "text": "In meiner wissenschaftlichen Untersuchung zum Strukturwandel der Arbeit wird deutlich, dass Algorithmen menschliche Expertise keineswegs obsolet machen. Vielmehr sollte ein symbiotisches Verhältnis im Vordergrund stehen, bei dem künstliche Intelligenz als assistierendes Werkzeug fungiert, während die finale Entscheidungskompetenz stets beim Menschen verbleiben muss."}], "questions": [{"question_num": 3, "question_type": "richtig_falsch", "question_text": "Frau Dr. Al-Mansoori fordert, dass künstliche Intelligenz menschliche Arbeitskräfte vollständig ersetzen sollte, um Fehler zu minimieren.", "correct_answer": "Falsch"}]}, {"conv_num": 4, "sprecher": [{"name": "Herr Schoppe", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Herr Schoppe", "text": "Als Interessenvertreter der Arbeitnehmer blicke ich mit Sorge auf das unkontrollierte Vordringen digitaler Automatisierungsprozesse, da hierbei oft Rationalisierungsmaßnahmen zulasten der Beschäftigten durchgeführt werden. Dennoch wäre es naiv zu glauben, wir könnten diesen Trend aufhalten; es gilt vielmehr, den Wandel sozialverträglich zu gestalten und Weiterbildungen zu forcieren."}], "questions": [{"question_num": 4, "question_type": "richtig_falsch", "question_text": "Herr Schoppe lehnt den Einzug technologischer Neuerungen prinzipiell ab, da er Arbeitsplätze gefährdet sieht.", "correct_answer": "Falsch"}]}, {"conv_num": 5, "sprecher": [{"name": "Frau Mertens", "voice_id": "Aoede"}], "script_segments": [{"sprecher": "Frau Mertens", "text": "Für unser Startup bietet die Cloud-Infrastruktur ungeahnte Möglichkeiten zur Skalierung unserer Dienstleistungen, ganz ohne astronomische Vorabinvestitionen. Wir müssen uns jedoch im Klaren darüber sein, dass die Speicherung sensibler Kundendaten auf externen Servern erhebliche datenschutzrechtliche Risiken birgt, deren Absicherung oberste Priorität genießen muss."}], "questions": [{"question_num": 5, "question_type": "richtig_falsch", "question_text": "Frau Mertens weist darauf hin, dass neben den praktischen Vorteilen auch Risiken bezüglich des Datenschutzes bestehen.", "correct_answer": "Richtig"}]}]}, {"aufgabe_num": 2, "typ": "gespraech", "title": "Aufgabe 2", "instruction": "Sie hören jetzt ein Gespräch. Kreuzen Sie an: Sind die Aussagen richtig oder falsch? Sie hören das Gespräch zweimal.", "heard_times": 2, "preparation_seconds": 60, "sprecher": [{"name": "Moderatorin", "voice_id": "Aoede"}, {"name": "Herr Dr. Schäfer", "voice_id": "Charon"}], "script_segments": [{"sprecher": "Moderatorin", "text": "Guten Tag, liebe Hörerinnen und Hörer. Heute im Studio begrüße ich den renommierten Mobilitätsforscher Dr. Roland Schäfer. Herr Dr. Schäfer, die Vision der autofreien Innenstadt spaltet die Gemüter leidenschaftlich. Warum ist diese fundamentale Transformation dennoch unumgänglich?"}, {"sprecher": "Herr Dr. Schäfer", "text": "Guten Tag. Nun, betrachten wir die gesundheitlichen Belastungen durch Abgase und Lärm sowie den immensen Flächenverbrauch parkender Fahrzeuge, so wird schnell klar, dass der Status quo nicht zukunftsfähig ist. Es geht keineswegs darum, urbane Mobilität gänzlich zu verhindern, sondern sie effizienter und lebenswerter zu gestalten, indem wir den öffentlichen Raum gerechter aufteilen."}, {"sprecher": "Moderatorin", "text": "Viele Ladenbesitzer fürchten jedoch massive Umsatzeinbußen, wenn Kunden nicht mehr unmittelbar mit dem Pkw vorfahren können. Ist diese Sorge Ihrer Ansicht nach berechtigt?"}, {"sprecher": "Herr Dr. Schäfer", "text": "Empirische Studien aus europäischen Städten, die diesen Schritt bereits gewagt haben, zeigen exakt das Gegenteil. Fußgänger verweilen deutlich länger in verkehrsberuhigten Einkaufsstraßen und geben statistisch gesehen sogar mehr Geld aus als Autofahrer. Der Einzelhandel profitiert letztlich von einer gesteigerten Aufenthaltsqualität, obgleich die anfängliche Skepsis durchaus nachvollziehbar ist."}, {"sprecher": "Moderatorin", "text": "Dennoch wirft das Konzept brisante Fragen der sozialen Gerechtigkeit auf. Nicht jede Familie kann sich kostspielige Lastenfahrräder leisten oder weite Strecken mühelos zu Fuß zurücklegen."}, {"sprecher": "Herr Dr. Schäfer", "text": "Das ist ein absolut entscheidender Einwand. Die Reduzierung des Individualverkehrs darf unter keinen Umständen zu einer sozialen Ausgrenzung führen. Flankierend muss ein massiver, staatlich subventionierter Ausbau des öffentlichen Personennahverkehrs stattfinden. Nur wenn Tarife sozial verträglich gestaltet werden, schaffen wir echte Alternativen für alle Bevölkerungsschichten."}, {"sprecher": "Moderatorin", "text": "Wenn wir jedoch auf die gegenwärtige politische Realität in Deutschland blicken, dauert die Umsetzung solcher Infrastrukturprojekte aufgrund bürokratischer Hürden oft Jahrzehnte. Verpassen wir hier schlichtweg den Anschluss?"}, {"sprecher": "Herr Dr. Schäfer", "text": "In der Tat sind unsere Planungsverfahren oft von einer erdrückenden Langsamkeit geprägt. Während andere europäische Metropolen wie Kopenhagen oder Paris mutig voranschreiten und experimentelle Verkehrsversuche wagen, verharren wir oft in zähen Debatten. Ein bisschen mehr Pragmatismus und Innovationsmut stünde uns im Ländervergleich gut zu Gesicht."}, {"sprecher": "Moderatorin", "text": "Gilt das Kopenhagener Modell denn uneingeschränkt für alle Regionen? Ein Pendler aus einer ländlichen Gemeinde hat schließlich grundlegend andere Bedürfnisse als ein Bewohner der Innenstadt."}, {"sprecher": "Herr Dr. Schäfer", "text": "Absolut, das ist der kritische Knackpunkt. Ein einfaches Einheitskonzept existiert nicht. Während in Ballungsräumen auf das Auto verzichtet werden kann, benötigt der ländliche Raum flexible On-Demand-Shuttles und eine nahtlose Anbindung an Schienennetze. Ein bloßer Transfer urbaner Konzepte auf das Land würde dort zu einer fatalen Isolation der Bürger führen."}, {"sprecher": "Moderatorin", "text": "Umfragen verdeutlichen zudem, dass viele Bürger solche einschneidenden Veränderungen vehement ablehnen, weil sie sich politisch übergangen fühlen. Wie lässt sich hier Akzeptanz generieren?"}, {"sprecher": "Herr Dr. Schäfer", "text": "Indem wir die betroffene Bevölkerung von Anfang an aktiv in die Planungsprozesse einbeziehen. Transparente Bürgerbeteiligungen sind keine lästige Pflichtaufgabe, sondern das eigentliche Fundament des Erfolgs. Wenn die Menschen die Vorteile – wie sicherere Schulwege und sauberere Luft – selbst mitgestalten können, schwindet auch der anfängliche Widerstand."}, {"sprecher": "Moderatorin", "text": "Herr Dr. Schäfer, ich danke Ihnen ganz herzlich für diese klärenden Einblicke in die Mobilität von morgen."}, {"sprecher": "Herr Dr. Schäfer", "text": "Ich danke Ihnen für die Einladung."}], "questions": [{"question_num": 6, "question_type": "richtig_falsch", "question_text": "Herr Dr. Schäfer plädiert dafür, den Autoverkehr in Großstädten ohne jegliche Übergangsfristen sofort einzustellen.", "correct_answer": "Falsch"}, {"question_num": 7, "question_type": "richtig_falsch", "question_text": "Dr. Schäfer behauptet, dass der Einzelhandel durch autofreie Zonen langfristig wirtschaftlichen Schaden erleide.", "correct_answer": "Falsch"}, {"question_num": 8, "question_type": "richtig_falsch", "question_text": "Um soziale Ungleichheit zu vermeiden, fordert der Experte eine stärkere finanzielle Unterstützung des öffentlichen Personennahverkehrs.", "correct_answer": "Richtig"}, {"question_num": 9, "question_type": "richtig_falsch", "question_text": "Laut Dr. Schäfer lässt sich das Kopenhagener Modell ohne Anpassungen direkt auf jede beliebige Kleinstadt übertragen.", "correct_answer": "Falsch"}, {"question_num": 10, "question_type": "richtig_falsch", "question_text": "Bestimmte Bevölkerungsgruppen stehen den Veränderungen skeptisch gegenüber, weshalb der Experte Partizipationsprozesse für essenziell hält.", "correct_answer": "Richtig"}, {"question_num": 11, "question_type": "richtig_falsch", "question_text": "Die Moderatorin äußert Bedenken, dass ländliche Regionen durch die Verkehrswende den Anschluss verlieren könnten.", "correct_answer": "Richtig"}, {"question_num": 12, "question_type": "richtig_falsch", "question_text": "Dr. Schäfer meint, dass politische Entscheidungen im Bereich der Mobilität in Deutschland bereits überdurchschnittlich schnell umgesetzt werden.", "correct_answer": "Falsch"}, {"question_num": 13, "question_type": "richtig_falsch", "question_text": "Der Experte empfiehlt, Lastfahrräder ausschließlich an einkommensstarke Haushalte zu verteilen.", "correct_answer": "Falsch"}, {"question_num": 14, "question_type": "richtig_falsch", "question_text": "Dem Experten zufolge scheitern städtebauliche Großprojekte häufig dann, wenn die Meinung der Bürger nicht berücksichtigt wird.", "correct_answer": "Richtig"}, {"question_num": 15, "question_type": "richtig_falsch", "question_text": "Dr. Schäfer fordert als wichtigste Maßnahme die sofortige Abschaffung aller Parkplätze in ländlichen Gebieten.", "correct_answer": "Falsch"}]}, {"aufgabe_num": 3, "typ": "ansagen", "title": "Aufgabe 3", "instruction": "Sie hören fünf kurze Texte aus dem Radio und anderen Medien. Kreuzen Sie an: Sind die Aussagen richtig oder falsch? Sie hören jeden Text zweimal.", "heard_times": 2, "preparation_seconds": 30, "ansagen": [{"ansage_num": 1, "sprecher": "Ansagerin", "voice_id": "Aoede", "text": "Achtung, liebe Bürgerinnen und Bürger der Gemeinde Waldbronn. Im Rahmen unserer Nachhaltigkeitsoffensive weisen wir darauf hin, dass ab dem kommenden Ersten des Monats die neuen, verschärften Richtlinien zur Mülltrennung in Kraft treten. Die Entsorgung von Elektroaltgeräten über den Hausmüll wird ab diesem Zeitpunkt mit empfindlichen Bußgeldern geahndet. Bitte nutzen Sie ausschließlich die kostenfreien Abgabestellen am städtischen Wertstoffhof.", "question_num": 16, "question_type": "richtig_falsch", "question_text": "Wer ab dem nächsten Monat elektrische Kleingeräte falsch entsorgt, muss mit einer Geldstrafe rechnen.", "correct_answer": "Richtig"}, {"ansage_num": 2, "sprecher": "Ansager", "voice_id": "Charon", "text": "Sehr geehrte Fahrgäste, wegen einer kurzfristig anberaumten Gleisreparatur im Bereich des Hauptbahnhofs kommt es heute auf der Strecke nach Hamburg zu einer Umleitung. Der Zug mit der Nummer ICE 582 wird über die Güterumgehungsbahn geleitet, wodurch sich die Fahrzeit um voraussichtlich zwanzig Minuten verlängert. Wir bitten, diese Verzögerung bei Ihrer Reiseplanung zu berücksichtigen.", "question_num": 17, "question_type": "richtig_falsch", "question_text": "Aufgrund von Baumaßnahmen erreicht der Zug nach Hamburg sein Ziel heute plangemäß, jedoch über eine Ausweichstrecke.", "correct_answer": "Falsch"}, {"ansage_num": 3, "sprecher": "Ansagerin", "voice_id": "Aoede", "text": "Willkommen beim telefonischen Kundenservice der Hanse-Krankenkasse. Um Ihnen lästige Wartezeiten zu ersparen, bieten wir ab sofort die digitale Übermittlung von Arbeitsunfähigkeitsbescheinigungen an. Laden Sie hierzu einfach unsere verifizierte Service-App herunter und fotografieren Sie das Dokument. Eine postalische Zusendung an unsere Zentrale ist somit nicht mehr erforderlich, sofern die Erfassung erfolgreich war.", "question_num": 18, "question_type": "richtig_falsch", "question_text": "Die Übermittlung von Krankmeldungen auf rein digitalem Weg setzt die Nutzung einer speziellen Anwendung voraus.", "correct_answer": "Richtig"}, {"ansage_num": 4, "sprecher": "Ansager", "voice_id": "Charon", "text": "Liebe Besucher des Kulturzentrums \'Gutenberg\'. Wir müssen Sie leider darüber informieren, dass die für heute Abend angekündigte Podiumsdiskussion zum Thema \'Chancengleichheit in der modernen Bildung\' aufgrund einer plötzlichen Erkrankung der Hauptreferentin kurzfristig verschoben werden muss. Bereits erworbene Eintrittskarten behalten für den Ersatztermin im kommenden Monat selbstverständlich ihre Gültigkeit.", "question_num": 19, "question_type": "richtig_falsch", "question_text": "Die geplante Kulturveranstaltung entfällt ersatzlos, weshalb die gezahlten Eintrittspreise in Kürze automatisch erstattet werden.", "correct_answer": "Falsch"}, {"ansage_num": 5, "sprecher": "Ansagerin", "voice_id": "Aoede", "text": "Achtung am Gate B12 für die Fluggäste nach London. Aus Sicherheitsgründen weisen wir nachdrücklich darauf hin, dass die Mitnahme von Lithium-Ionen-Akkus sowie externen Powerbanks im aufgegebenen Gepäck strengstens untersagt ist. Diese Gegenstände müssen zwingend im Handgepäck mitgeführt werden, um im Falle einer Überhitzung ein rechtzeitiges Eingreifen der Crew zu gewährleisten. Bitte prüfen Sie Ihr Reisegepäck vor dem Einchecken.", "question_num": 20, "question_type": "richtig_falsch", "question_text": "Aus Sicherheitsgründen dürfen Powerbanks nicht in den Koffern transportiert werden, die für den Frachtraum bestimmt sind.", "correct_answer": "Richtig"}]}], "total_questions": 15, "duration_minutes": 30}, "sprachbausteine": {"aufgaben": [{"aufgabe_num": 1, "typ": "lueckentext_mc", "text_with_gaps": "Sehr geehrte Damen und Herren,\\n\\ndie vorliegende Untersuchung zur flexiblen Arbeitsplatzgestaltung verdeutlicht, dass die fortschreitende Digitalisierung die moderne Arbeitswelt nachhaltig verändert hat. Ein Großteil der Befragten gibt an, {21} die Einführung von Homeoffice-Modellen eine deutliche Entlastung im Alltag erfahren zu haben. Dennoch darf keineswegs übersehen werden, dass diese Flexibilität oft mit {22} schleichenden Entgrenzung der Arbeitszeit einhergeht. Viele Beschäftigte neigen nämlich dazu, unbezahlte Überstunden zu leisten, {23} sie sich laut Dienstplan eigentlich in ihrer Freizeit befinden sollten.\\n\\nEs wird daher dringend empfohlen, präventive Maßnahmen {24} ergreifen, um drohenden psychischen Belastungen rechtzeitig entgegenzuwirken. In diesem Zusammenhang {25} in der Fachliteratur wiederholt berichtet, dass jene Unternehmen, die klare Erreichbarkeitsgrenzen etabliert haben, eine weitaus höhere Mitarbeiterzufriedenheit verzeichnen. Ein führender Arbeitspsychologe betonte auf dem letzten Kongress, dass eine von Vertrauen geprägte Fehlerkultur für den langfristigen Erfolg essenziell {26}.\\n\\nSollten die gesetzlichen Rahmenbedingungen nicht bald an die digitale Realität angepasst {27}, stünden viele Betriebe in naher Zukunft vor massiven rechtlichen Herausforderungen. Es gilt nunmehr, den anstehenden Transformationsprozess so zu gestalten, {28} sowohl die wirtschaftlichen Interessen des Arbeitgebers als auch das gesundheitliche Wohlbefinden der Angestellten gleichermaßen berücksichtigt werden können. Dies erfordert jedoch die ausdrückliche Bereitschaft {29} Führungskräfte, traditionelle Kontrollmechanismen schrittweise abzubauen. Letztlich lässt sich konstatieren, dass der Erfolg dieser tiefgreifenden Transformation maßgeblich {30} der Qualität einer partnerschaftlichen Kommunikation abhängt.\\n\\nMit freundlichen Grüßen\\n\\nDr. Stefan Meier, Institut für Arbeitspsychologie", "options": [{"question_num": 21, "a": "durch", "b": "wegen", "c": "trotz", "correct_answer": "a"}, {"question_num": 22, "a": "eine", "b": "einer", "c": "einen", "correct_answer": "b"}, {"question_num": 23, "a": "während", "b": "indem", "c": "sodass", "correct_answer": "a"}, {"question_num": 24, "a": "zu", "b": "um", "c": "an", "correct_answer": "a"}, {"question_num": 25, "a": "wird", "b": "wurde", "c": "ist", "correct_answer": "a"}, {"question_num": 26, "a": "wäre", "b": "sei", "c": "ist", "correct_answer": "b"}, {"question_num": 27, "a": "würden", "b": "worden", "c": "werden", "correct_answer": "c"}, {"question_num": 28, "a": "wie", "b": "sodass", "c": "dass", "correct_answer": "c"}, {"question_num": 29, "a": "der", "b": "von", "c": "an", "correct_answer": "a"}, {"question_num": 30, "a": "von", "b": "aus", "c": "an", "correct_answer": "a"}]}, {"aufgabe_num": 2, "typ": "lueckentext_wortbank", "text_with_gaps": "Die stetig fortschreitende Transformation moderner Großstädte hin zu einer klimafreundlichen und nachhaltigen Lebensweise stellt Kommunen weltweit vor enorme organisatorische Herausforderungen. Im {31} steht dabei zweifellos die drastische Reduzierung schädlicher Treibhausgase durch den systematischen und flächendeckenden Ausbau des öffentlichen Personennahverkehrs. Um dieses ehrgeizige Ziel zeitnah zu realisieren, müssen innovative Mobilitätskonzepte nicht nur theoretisch erdacht, sondern auch konsequent in die alltägliche {32} umgesetzt werden. Ein wichtiger erster Schritt stellt in vielen Metropolen der massive Ausbau geschützter Fahrradwege dar, um auf diese Weise die {33} für Radfahrer im dichten Straßenverkehr signifikant zu erhöhen.\\n\\nKritische Stimmen geben jedoch zu bedenken, dass die bloße Verringerung des motorisierten Individualverkehrs allein kaum ausreicht. Vielmehr müsse gleichzeitig ein grundsätzlicher {34} im alltäglichen Bewusstsein der Bürger stattfinden. Experten auf dem Gebiet der Stadtplanung betonen vehement, dass finanzielle Anreize wie stark vergünstigte Jahrestickets einen wesentlichen {35} zur notwendigen Mobilitätswende leisten können. Darüber hinaus {36} die großflächige Begrünung von Fassaden, Dächern und Plätzen das städtische Mikroklima positiv, indem sie der Entstehung von Hitzeinseln in heißen Sommermonaten effektiv entgegenwirkt.\\n\\nZudem müssen staatliche Ressourcen stets zielgerichtet {37} werden, um auch einkommensschwachen Haushalten die gleichberechtigte Teilhabe an umweltfreundlichen Alternativen dauerhaft zu {38}. Nur wenn ökologische Nachhaltigkeit und soziale Gerechtigkeit Hand in Hand gehen, lässt sich eine breite gesellschaftliche Akzeptanz langfristig {39}. Es ist daher von entscheidender Bedeutung, alle Gruppen der Bevölkerung in diese zukunftsweisenden Prozesse aktiv {40}.", "wortbank": [{"id": "a", "word": "BEITRAG"}, {"id": "b", "word": "BEEINFLUSST"}, {"id": "c", "word": "EINZUBINDEN"}, {"id": "d", "word": "ERREICHEN"}, {"id": "e", "word": "ERMÖGLICHEN"}, {"id": "f", "word": "GEFÖRDERT"}, {"id": "g", "word": "EINGESETZT"}, {"id": "h", "word": "MITTELPUNKT"}, {"id": "i", "word": "NACHHALTIGKEIT"}, {"id": "j", "word": "PRAXIS"}, {"id": "k", "word": "SICHERHEIT"}, {"id": "l", "word": "VERÄNDERUNG"}, {"id": "m", "word": "WANDEL"}, {"id": "n", "word": "WIRKUNG"}, {"id": "o", "word": "ZUVERLÄSSIGKEIT"}], "options": [{"question_num": 31, "correct_answer": "h"}, {"question_num": 32, "correct_answer": "j"}, {"question_num": 33, "correct_answer": "k"}, {"question_num": 34, "correct_answer": "m"}, {"question_num": 35, "correct_answer": "a"}, {"question_num": 36, "correct_answer": "b"}, {"question_num": 37, "correct_answer": "g"}, {"question_num": 38, "correct_answer": "e"}, {"question_num": 39, "correct_answer": "d"}, {"question_num": 40, "correct_answer": "c"}]}], "total_questions": 20, "duration_minutes": 30}, "schreiben": {"total_time_minutes": 30, "aufgaben": [{"aufgabe_num": 1, "aufgabe_typ": "erörterung", "aufgabe": "Schreiben Sie einen argumentativen Aufsatz zum Thema \'Beruf, Weiterbildung oder gesellschaftliches Thema\'.\\nGehen Sie dabei auf folgende Punkte ein:\\n- Vorteile und Chancen\\n- Nachteile und Risiken\\n- Ihre eigene Position mit Begründung", "min_words": 180, "max_words": 250}]}, "sprechen": {"total_time_minutes": 15, "vorbereitungszeit_minutes": 20, "teile": [{"teil_num": 1, "titel": "Einander kennenlernen", "instructions": "Stellen Sie sich vor und beantworten Sie die Fragen des Prüfers.", "themen": ["Name", "Herkunft", "Wohnsituation", "Beruf/Studium", "Deutschlernen", "Hobbys"], "fragen": [{"frage_num": 1, "frage_text": "[warm] Guten Tag! Willkommen. Wie heißen Sie und woher kommen Sie?", "needs_audio": true}, {"frage_num": 2, "frage_text": "Was machen Sie beruflich oder studieren Sie gerade?", "needs_audio": true}, {"frage_num": 3, "frage_text": "Wie lange lernen Sie schon Deutsch und warum?", "needs_audio": true}, {"frage_num": 4, "frage_text": "Was machen Sie in Ihrer Freizeit?", "needs_audio": true}]}, {"teil_num": 2, "titel": "Uber ein Thema sprechen", "instructions": "Jede Person hat einen kurzen Text zum Thema \\"Nachhaltigkeit im Alltag\\" gelesen. Stellen Sie Ihre Meinung vor und diskutieren Sie dann gemeinsam.", "thema": "Nachhaltigkeit im Alltag", "meinungen": [{"person": "A", "zitat": "\\"Ich finde Nachhaltigkeit im Alltag sehr positiv, weil man flexibler und produktiver ist.\\""}, {"person": "B", "zitat": "\\"Ich sehe Nachhaltigkeit im Alltag kritisch - die Grenzen zwischen Arbeit und Freizeit verschwimmen.\\""}], "fragen": [{"frage_num": 5, "frage_text": "Was haben Sie uber Nachhaltigkeit im Alltag gelesen? Stellen Sie Ihre Meinung vor.", "needs_audio": true}, {"frage_num": 6, "frage_text": "Was denken Sie - welche Meinung uberzeugt mehr?", "needs_audio": true}, {"frage_num": 7, "frage_text": "Haben Sie eigene Erfahrungen mit diesem Thema?", "needs_audio": true}]}, {"teil_num": 3, "titel": "Gemeinsam etwas planen", "instructions": "Planen Sie gemeinsam eine Veranstaltung fur Ihre Sprachschule.", "szenario": "Ihre Sprachschule mochte ein Sommerfest fur alle Teilnehmer organisieren.", "planungspunkte": ["Wann und wo?", "Programm und Aktivitaten", "Essen und Getranke", "Aufgabenverteilung"], "fragen": [{"frage_num": 8, "frage_text": "Wann und wo soll das Fest stattfinden? Was schlagen Sie vor?", "needs_audio": true}, {"frage_num": 9, "frage_text": "Was soll auf dem Programm stehen?", "needs_audio": true}, {"frage_num": 10, "frage_text": "Wer ubernimmt welche Aufgaben fur das Fest?", "needs_audio": true}]}]}, "status": "pending_audio", "telc_level": "B2", "exam_type": "telc", "pathway": "telc_b2", "audio_progress": 0}')
